<template>
  <div class="pl-root">
    <main class="pl-body">
      <section class="pl-card">
        <!-- ── Card header ──────────────────────────────────────────── -->
        <div class="pl-card__head">
          <div class="pl-card__head-left">
            <div class="pl-card__chip pl-card__chip--indigo">Positions</div>
            <h2 class="pl-card__title">Position Register</h2>
          </div>
          <div class="pl-card__head-right">
            <v-btn depressed color="primary" small @click="createPosition">
              <v-icon small left>mdi-plus</v-icon>
              Add Position
            </v-btn>
          </div>
        </div>

        <!-- ── Filters ─────────────────────────────────────────────── -->
        <v-card-text class="pb-1 pt-3">
          <v-row dense>
            <v-col cols="12" sm="6" md="4">
              <v-autocomplete
                v-model="filter.designation"
                :items="designationOptions"
                label="Filter by designation"
                dense
                outlined
                hide-details
                clearable
                prepend-inner-icon="mdi-magnify"
                class="ma-1"
                @change="onFilterChange"
                @click:clear="onFilterChange"
              />
            </v-col>
            <v-col cols="12" sm="6" md="3">
              <v-autocomplete
                v-model="filter.department"
                :items="departmentOptions"
                label="Filter by department"
                dense
                outlined
                hide-details
                clearable
                prepend-inner-icon="mdi-office-building-outline"
                class="ma-1"
                @change="onFilterChange"
                @click:clear="onFilterChange"
              />
            </v-col>
            <v-col cols="12" sm="6" md="3">
              <v-autocomplete
                v-model="filter.facility"
                :items="facilityOptions"
                label="Filter by facility"
                dense
                outlined
                hide-details
                clearable
                prepend-inner-icon="mdi-hospital-building"
                class="ma-1"
                @change="onFilterChange"
                @click:clear="onFilterChange"
              />
            </v-col>
            <v-col cols="12" sm="auto" class="d-flex align-center">
              <v-btn
                v-if="hasActiveFilters"
                text
                small
                color="red darken-1"
                class="ma-1"
                @click="resetFilters"
              >
                <v-icon small left>mdi-close</v-icon>
                Clear filters
              </v-btn>
            </v-col>
          </v-row>
        </v-card-text>

        <!-- ── Data table ──────────────────────────────────────────── -->
        <v-data-table
          :headers="tableHeaders"
          :items="positions"
          :loading="loading"
          loading-text="Loading positions…"
          no-data-text="No positions match the current filters"
          :server-items-length="totalPositions"
          :options.sync="tableOptions"
          :footer-props="{
            'items-per-page-options': [10, 15, 25, 50],
            'items-per-page-text': 'Rows per page',
          }"
          class="elevation-0"
          @click:row="openPosition"
        >
          <!-- Designation -->
          <template #[`item.designation`]="{ item }">
            <div class="pl-table__primary">{{ item.designation || "—" }}</div>
          </template>

          <!-- Department -->
          <template #[`item.department`]="{ item }">
            <span class="pl-table__muted">{{ item.department || "—" }}</span>
          </template>

          <!-- Facility -->
          <template #[`item.facility`]="{ item }">
            <span class="pl-table__muted">{{ item.facility || "—" }}</span>
          </template>

          <!-- Grade pill -->
          <template #[`item.grade`]="{ item }">
            <span v-if="item.grade" class="pl-grade">{{ item.grade }}</span>
            <span v-else class="pl-table__muted">—</span>
          </template>

          <!-- Max practitioners -->
          <template #[`item.maximumPractitioners`]="{ item }">
            <span class="pl-max-count">{{
              item.maximumPractitioners != null
                ? item.maximumPractitioners
                : "—"
            }}</span>
          </template>

          <!-- Status -->
          <template #[`item.status`]="{ item }">
            <span
              v-if="item.status"
              class="pl-status-pill"
              :class="'pl-status-pill--' + statusKey(item.status)"
            >
              <span class="pl-status-pill__dot"></span>
              {{ item.status }}
            </span>
            <span v-else class="pl-table__muted">—</span>
          </template>

          <!-- Row actions -->
          <template #[`item.actions`]="{ item }">
            <v-btn
              icon
              small
              title="Edit position"
              @click.stop="editPosition(item)"
            >
              <v-icon small>mdi-pencil-outline</v-icon>
            </v-btn>
          </template>
        </v-data-table>
      </section>
    </main>
  </div>
