<script>
const POS_PROFILE =
  "http://ihris.org/fhir/StructureDefinition/position-profile";
const DES_PROFILE =
  "http://ihris.org/fhir/StructureDefinition/ls-designation-profile";

const EXT = {
  NAME: "http://ihris.org/fhir/StructureDefinition/ihris-basic-name",
  DESIGNATION: "http://ihris.org/fhir/StructureDefinition/designation",
  GRADE: "http://ihris.org/fhir/StructureDefinition/salary-grade",
  FACILITY: "http://ihris.org/fhir/StructureDefinition/facility",
  DEPARTMENT: "http://ihris.org/fhir/StructureDefinition/department",
  MAX: "http://ihris.org/fhir/StructureDefinition/maximum-practitioners",
  STATUS: "http://ihris.org/fhir/StructureDefinition/position-status",
};

export default {
  name: "PositionList",
  props: ["queries"],

  data() {
    return {
      positions: [],
      loading: false,
      totalPositions: 0,

      filter: {
        designation: null,
        department: null,
        facility: null,
      },
      filterDebounce: null,

      designationOptions: [],
      departmentOptions: [],
      facilityOptions: [],

      tableOptions: { page: 1, itemsPerPage: 10 },
      prevPage: 0,
      link: [],

      tableHeaders: [
        { text: "", value: "actions", sortable: false, width: "52px" },
        { text: "Designation", value: "designation", width: "220px" },
        { text: "Department", value: "department" },
        { text: "Facility", value: "facility" },
        { text: "Grade", value: "grade" },
        {
          text: "Max Positions",
          value: "maximumPractitioners",
          align: "center",
        },
        { text: "Status", value: "status", sortable: false },
      ],
    };
  },

  computed: {
    hasActiveFilters() {
      return (
        !!this.filter.designation ||
        !!this.filter.department ||
        !!this.filter.facility
      );
    },
  },

  watch: {
    tableOptions: {
      handler() {
        this.loadPositions(false);
      },
      deep: true,
    },
  },

  async mounted() {
    await Promise.all([this.loadPositions(true), this.loadFilterOptions()]);
  },

  methods: {
    // ── FHIR helpers ─────────────────────────────────────────────────
    extValue(resource, url, key) {
      const ext = (resource.extension || []).find((e) => e.url === url);
      return ext ? ext[key] : null;
    },

    // ── Load positions ───────────────────────────────────────────────
    // HAPI's Bundle.link.url echoes back the FHIR server's own configured
    // base (fhir:base in config, e.g. http://.../lesotho/fhir - no slash
    // before the query string), not the app's public /fhir proxy path.
    // Fetching that absolute URL directly from the browser bypasses the
    // app's auth/session layer and hits a different origin, so pull out
    // just the query string and replay it against our own /fhir/Basic
    // route instead of guessing at the server's URL shape.
    toRelativeFhirUrl(absoluteUrl) {
      const search = new URL(absoluteUrl).search;
      return `/fhir/Basic${search}`;
    },

    buildFhirUrl() {
      const params = new URLSearchParams({
        _profile: POS_PROFILE,
        _count: this.tableOptions.itemsPerPage,
        _total: "accurate",
        _sort: "-_lastUpdated",
      });
      params.append("_include", "Basic:posdesignation");
      params.append("_include", "Basic:facility");
      params.append("_include", "Basic:salarygrade");
      if (this.filter.designation)
        params.set("posdesignation", this.filter.designation);
      if (this.filter.department)
        params.set("department", this.filter.department);
      if (this.filter.facility) params.set("facility", this.filter.facility);
      return `/fhir/Basic?${params}`;
    },

    async loadPositions(restart) {
      if (this.loading) return;
      this.loading = true;
      if (restart) {
        this.tableOptions.page = 1;
        this.link = [];
        this.prevPage = 0;
      }
      try {
        const { page } = this.tableOptions;
        let url;

        if (page === 1 || this.link.length === 0) {
          url = this.buildFhirUrl();
        } else if (page === this.prevPage + 1) {
          const next = this.link.find((l) => l.relation === "next");
          url = next ? this.toRelativeFhirUrl(next.url) : this.buildFhirUrl();
        } else if (page === this.prevPage - 1) {
          const prev = this.link.find((l) => l.relation === "previous");
          url = prev ? this.toRelativeFhirUrl(prev.url) : this.buildFhirUrl();
        } else {
          url = this.buildFhirUrl();
        }

        const res = await fetch(url);
        const data = await res.json();

        this.link = data.link || [];
        this.prevPage = page;

        const entries = data.entry || [];
        const posEntries = entries.filter(
          (e) => e.search && e.search.mode === "match",
        );
        const includedEntries = entries.filter(
          (e) => !e.search || e.search.mode === "include",
        );

        const includedBasicByRef = includedEntries
          .filter((e) => e.resource && e.resource.resourceType === "Basic")
          .reduce((acc, e) => {
            acc["Basic/" + e.resource.id] = e.resource;
            return acc;
          }, {});

        const facilityNameById = includedEntries
          .filter((e) => e.resource && e.resource.resourceType === "Location")
          .reduce((acc, e) => {
            if (e.resource.name) acc[e.resource.id] = e.resource.name;
            return acc;
          }, {});

        this.positions = posEntries.map((e) => {
          const r = e.resource;
          const desRef = this.extValue(r, EXT.DESIGNATION, "valueReference");
          const desRes =
            desRef && desRef.reference
              ? includedBasicByRef[desRef.reference]
              : null;
          const designation = desRes
            ? this.extValue(desRes, EXT.NAME, "valueString")
            : (desRef && desRef.display) || null;

          const deptCoding = this.extValue(r, EXT.DEPARTMENT, "valueCoding");
          const facRef = this.extValue(r, EXT.FACILITY, "valueReference");
          const facId =
            facRef &&
            facRef.reference &&
            facRef.reference.startsWith("Location/")
              ? facRef.reference.split("/")[1]
              : null;
          const gradeRef = this.extValue(r, EXT.GRADE, "valueReference");
          const gradeRes =
            gradeRef && gradeRef.reference
              ? includedBasicByRef[gradeRef.reference]
              : null;
          const statusCoding = this.extValue(r, EXT.STATUS, "valueCoding");

          return {
            id: r.id,
            designation:
              designation || this.extValue(r, EXT.NAME, "valueString") || "",
            department:
              (deptCoding && (deptCoding.display || deptCoding.code)) || "",
            facility:
              (facId && facilityNameById[facId]) ||
              (facRef && facRef.display) ||
              "",
            grade:
              (gradeRes && this.extValue(gradeRes, EXT.NAME, "valueString")) ||
              (gradeRef && gradeRef.display) ||
              "",
            maximumPractitioners: this.extValue(r, EXT.MAX, "valueInteger"),
            status:
              (statusCoding && (statusCoding.display || statusCoding.code)) ||
              "",
          };
        });

        this.totalPositions =
          data.total != null ? data.total : this.positions.length;
      } catch (err) {
        console.error("loadPositions error", err);
        this.positions = [];
      } finally {
        this.loading = false;
      }
    },

    // ── Load dropdown options ────────────────────────────────────────
    async loadFilterOptions() {
      await Promise.all([
        this.loadDesignationOptions(),
        this.loadDepartmentOptions(),
        this.loadFacilityOptions(),
      ]);
    },

    async loadDesignationOptions() {
      try {
        const res = await fetch(
          `/fhir/Basic?_profile=${DES_PROFILE}&_count=1000&_sort=name`,
        );
        const data = await res.json();
        this.designationOptions = (data.entry || [])
          .map((e) => e.resource)
          .filter(Boolean)
          .map((r) => ({
            text: this.extValue(r, EXT.NAME, "valueString") || r.id,
            value: `Basic/${r.id}`,
          }))
          .filter((o) => o.text);
      } catch (e) {
        console.error("loadDesignationOptions error", e);
      }
    },

    async loadDepartmentOptions() {
      try {
        const items = await this.$fhirutils.expand(
          "http://ihris.org/fhir/ValueSet/departments-valueset",
        );
        this.departmentOptions = items.map((c) => ({
          text: c.display || c.code,
          value: c.code,
        }));
      } catch (e) {
        console.error("loadDepartmentOptions error", e);
      }
    },

    async loadFacilityOptions() {
      try {
        const res = await fetch(`/fhir/Location?_count=1000&_sort=name`);
        const data = await res.json();
        this.facilityOptions = (data.entry || [])
          .map((e) => e.resource)
          .filter(Boolean)
          .map((r) => ({
            text: r.name || r.id,
            value: `Location/${r.id}`,
          }))
          .filter((o) => o.text);
      } catch (e) {
        console.error("loadFacilityOptions error", e);
      }
    },

    // ── Filters ──────────────────────────────────────────────────────
    onFilterChange() {
      clearTimeout(this.filterDebounce);
      this.filterDebounce = setTimeout(() => {
        this.loadPositions(true);
      }, 400);
    },

    resetFilters() {
      this.filter = { designation: null, department: null, facility: null };
      this.loadPositions(true);
    },

    // ── Navigation ───────────────────────────────────────────────────
    createPosition() {
      this.$router.push({
        path: "/custom/create-position",
        query: { path: "/lesotho/components/position" },
      });
    },

    openPosition(item) {
      this.$router.push({
        path: "/custom/view-position",
        query: { path: "/lesotho/components/position", id: item.id },
      });
    },

    editPosition(item) {
      this.$router.push({
        path: "/custom/create-position",
        query: { path: "/lesotho/components/position", id: item.id },
      });
    },

    // ── Helpers ──────────────────────────────────────────────────────
    statusKey(status) {
      if (!status) return "default";
      const s = status.toLowerCase();
      if (s.includes("active") || s.includes("open")) return "active";
      if (s.includes("inactive") || s.includes("closed")) return "inactive";
      return "default";
    },
  },
};
</script>

